37: const SAVE_KEY='pokerampage-save';
38: const DEFAULT_STATE={starter:null,team:[],active:null,level:1,xp:0,hp:100,maxHp:100,berries:12,bag:[],equipped:{},zone:0,explores:0,quest:0,journal:[],bossDefeated:false,sound:false};
39: function cleanState(raw={}) {
40:   const s={...DEFAULT_STATE,...raw};
41:   s.team=Array.isArray(raw.team)?raw.team.filter(p=>p&&DEX[p.key]).map(p=>({key:p.key,level:Math.max(1,Number(p.level)||1)})):[];
42:   if(!s.team.length&&DEX[raw.active])s.team=[{key:raw.active,level:Math.max(1,Number(raw.level)||1)}];
43:   s.starter=DEX[s.starter]?s.starter:(DEX[raw.initial]?raw.initial:null);
44:   if(s.starter&&!s.team.some(p=>p.key===s.starter))s.team.unshift({key:s.starter,level:Math.max(1,Number(raw.level)||1)});
45:   s.active=DEX[s.active]&&s.team.some(p=>p.key===s.active)?s.active:(s.team[0]?.key||null);
46:   s.level=Math.max(1,Number(raw.level)||s.team.find(p=>p.key===s.active)?.level||1);
47:   s.xp=Math.max(0,Number(raw.xp)||0);s.maxHp=Math.max(1,Number(raw.maxHp)||100+(s.level-1)*12);s.hp=Math.max(0,Math.min(s.maxHp,Number.isFinite(Number(raw.hp))?Number(raw.hp):s.maxHp));
48:   s.berries=Math.max(0,Number(raw.berries)||0);
49:   s.bag=Array.isArray(raw.bag)?raw.bag.filter(id=>ITEMS[id]):[];
50:   s.equipped=raw.equipped&&typeof raw.equipped==='object'?raw.equipped:{};
51:   if(raw.equipment&&typeof raw.equipment==='string'&&ITEMS[raw.equipment]&&!s.equipped[s.active])s.equipped[s.active]=raw.equipment;
52:   // Migrate common names from earlier save formats without discarding progress.
53:   for(const [key,value] of Object.entries(s.equipped)){if(!DEX[key]||!ITEMS[value])delete s.equipped[key]}
54:   if(Array.isArray(raw.rescued))for(const key of raw.rescued)if(DEX[key]&&!s.team.some(p=>p.key===key))s.team.push({key,level:Math.max(1,s.level-1)});
55:   s.zone=Math.max(0,Math.min(ZONES.length-1,Number(raw.zone)||0));s.explores=Math.max(0,Number(raw.explores)||0);s.quest=Math.max(0,Math.min(3,Number(raw.quest)||0));
56:   s.journal=Array.isArray(raw.journal)?raw.journal.filter(x=>x&&typeof x==='object').slice(-30):[];s.bossDefeated=!!raw.bossDefeated;s.sound=!!raw.sound;
57:   if(!s.bag.length&&s.berries>0)s.bag=Array.from({length:Math.min(s.berries,12)},()=> 'berry');
58:   return s;
59: }
60: function loadState(){try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');return cleanState(raw||{})}catch(e){console.warn('Save inválido; iniciando uma jornada segura.',e);return cleanState()}}
61: let state=loadState();let battle=null;
62: function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){console.warn('Não foi possível salvar a jornada.',e)}}
63: function current(){return state.team.find(p=>p.key===state.active)||state.team[0]||{key:'bulbasaur',level:1}}
64: function itemStats(key=state.active){const item=ITEMS[state.equipped[key]]||{};return {attack:item.attack||0,defense:item.defense||0,maxHp:item.maxHp||0}}
65: function syncMaxHp(key=state.active){const previous=state.maxHp||100;state.maxHp=100+(state.level-1)*12+(itemStats(key).maxHp||0);state.hp=Math.min(state.maxHp,state.hp+(state.maxHp>previous?state.maxHp-previous:0))}
66: function sprite(key,klass=''){const p=DEX[key];if(!p)return '';return `<img class="pokemon-sprite ${klass}" src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${p.dex}.png" alt="${p.name}" onerror="this.onerror=null;this.src='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${p.dex}.png'">`}
67: function portrait(key,klass=''){const item=ITEMS[state.equipped[key]],wearClass={leafcloak:'wear-cape',goggles:'wear-glasses',twigcrown:'wear-crown',scarf:'wear-scarf',medal:'wear-medal'}[state.equipped[key]];return `<span class="pokemon-portrait ${klass}">${sprite(key)}${item?`<i class="wearable ${wearClass}" aria-label="${item.name}" title="${item.name}"></i>`:''}</span>`}
68: function modal(title,subtitle,body='',actions=''){modalRoot.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><div><span class="eyebrow accent">CRÔNICAS DA FLORESTA</span><h2>${title}</h2><p>${subtitle}</p></div><button class="close-modal" aria-label="Fechar">×</button></header><div class="modal-body">${body}</div>${actions?`<footer class="modal-actions">${actions}</footer>`:''}</section>`;$('.close-modal').onclick=()=>modalRoot.innerHTML=''}
69: let toastTimer;
70: function toast(message){const el=$('#eventToast');if(!el)return;el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2500)}
71: function addJournal(text){state.journal.unshift({time:`DIA 01 · ${String(state.explores).padStart(2,'0')}`,text});state.journal=state.journal.slice(0,30)}
72: function showStarter(){modal('Escolha seu primeiro parceiro','Um novo laço começa na Floresta de Veridiana. Escolha com o coração.',`<div class="starter-grid">${['bulbasaur','charmander','squirtle'].map(key=>`<button class="starter-card" data-starter="${key}">${sprite(key)}<b>${DEX[key].name}</b><small>${DEX[key].type}</small><span class="type-tag">${key==='bulbasaur'?'Planta':key==='charmander'?'Fogo':'Água'}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-starter]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.starter;state.starter=key;state.team=[{key,level:1}];state.active=key;state.hp=state.maxHp=100;state.berries=12;state.bag=Array.from({length:12},()=> 'berry');addJournal(`${DEX[key].name} tornou-se seu primeiro parceiro.`);save();modalRoot.innerHTML='';render();toast(`${DEX[key].name} começou a jornada com você!`)})}
73: function render(){const p=current();if(!p.key)return;state.level=p.level||state.level;syncMaxHp(state.active);$('#heroPokemon').innerHTML=portrait(state.active,'');$('#activePartner').innerHTML=`<div class="partner-main"><div class="partner-sprite">${portrait(state.active,'')}</div><div class="partner-info"><strong>${DEX[state.active].name}</strong><small>${DEX[state.active].type}</small><small>Nível ${state.level}</small></div></div><div class="partner-hp"><div><span>ENERGIA</span><b>${state.hp} / ${state.maxHp}</b></div><div class="hp-track"><i style="width:${Math.max(0,state.hp/state.maxHp*100)}%"></i></div></div>`;
74:   const others=state.team.filter(member=>member.key!==state.active);$('#teamList').innerHTML=others.slice(0,4).map(member=>`<button class="team-row" data-switch="${member.key}">${portrait(member.key,'small')}<span><b>${DEX[member.key].name}</b><small>Nível ${member.level||1} · ${DEX[member.key].type}</small></span><span class="switch-label">TROCAR</span></button>`).join('');$('#teamEmpty').style.display=others.length?'none':'';
75:   $('#partnerCount').textContent=String(state.team.length).padStart(2,'0');document.querySelector('.team-count').textContent=state.team.length;document.querySelector('.bag-count').textContent=state.bag.length;$('#statLevel').textContent=String(state.level).padStart(2,'0');const need=state.level*42;$('#statXp').textContent=`${state.xp} / ${need}`;$('#xpFill').style.width=`${Math.min(100,state.xp/need*100)}%`;$('#statHp').textContent=`${state.hp} / ${state.maxHp}`;$('#hpFill').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;$('#berries').textContent=state.berries;
76:   $('#exploreCount').textContent=String(state.explores+1).padStart(2,'0');const progress=Math.min(100,state.quest/3*100);$('.quest-progress i').style.width=`${progress}%`;$('.quest-status span').textContent=`${state.quest}/3 pistas`;$('.quest-status b').textContent=state.bossDefeated?'CONCLUÍDA':'EM ANDAMENTO';$('#objectiveText').textContent=state.bossDefeated?'As jaulas foram abertas. A floresta está segura.':state.quest>=3?'As pistas apontam para o responsável. Encontre-o na trilha.':'Investigue a trilha e descubra quem ameaça os Pokémon.';$('#threatLevel').textContent=state.quest>=3?'AMEAÇA IDENTIFICADA':state.quest?'ATENÇÃO':'BAIXO RISCO';
77:   $('#teamList').onclick=e=>{const row=e.target.closest('[data-switch]');if(row){switchPartner(row.dataset.switch);render()}};save()}
78: function explore(){if(!state.starter){showStarter();return}if(battle)return;if(state.hp<=0){toast('Seu parceiro precisa descansar no acampamento.');return}state.explores++;$('#exploreCount').textContent=String(state.explores+1).padStart(2,'0');const discoveries=['pidgey','caterpie','weedle','rattata'];
79:   if(state.quest>=3&&!state.bossDefeated&&(state.explores%3===0||state.explores>=7)){addJournal('Você encontrou o responsável pelas jaulas na clareira.');startBattle('rattata',{boss:true});render();return}
80:   const roll=Math.random();if(state.quest<3&&(roll<.48||state.explores<=3)){state.quest++;const clues=['Pegadas pequenas cercam uma jaula vazia.','Um pedaço de tecido ficou preso nos arbustos.','Você encontra marcas recentes perto da clareira.'];const text=clues[state.quest-1];addJournal(`Pista ${state.quest}/3: ${text}`);$('.discovery-row').innerHTML=`<div class="discovery-icon">🔎</div><div><b>${text}</b><small>Uma nova pista aproxima você da verdade.</small></div><span class="discovery-time">AGORA</span>`;toast(`Pista encontrada · ${state.quest}/3`);if(state.quest===3)state.zone=1;render();return}
81:   if(roll<.67){const key=discoveries[Math.floor(Math.random()*discoveries.length)];startBattle(key);render();return}
82:   if(roll<.82){const key=state.team.some(p=>p.key==='oddish')?'bellsprout':'oddish';showRescue(key);render();return}
83:   const found=['leafcloak','twigcrown','scarf','goggles','medal'][Math.floor(Math.random()*5)];if(state.bag.length<20)state.bag.push(found);state.berries++;state.bag.push('berry');addJournal(`Você encontrou ${ITEMS[found].name} e uma Baga Oran.`);$('.discovery-row').innerHTML=`<div class="discovery-icon">🎒</div><div><b>${ITEMS[found].name} encontrada</b><small>Também encontrou uma Baga Oran.</small></div><span class="discovery-time">AGORA</span>`;render();toast(`Tesouro encontrado: ${ITEMS[found].name}`)}
