/* Procedural Three.js diorama: all scenery and companions are real meshes. */
(() => {
  const canvas = document.getElementById('forestCanvas');
  if (!canvas || !window.THREE) return;
  const T = window.THREE;
  const scene = new T.Scene();
  scene.background = new T.Color('#9cbd9a');
  scene.fog = new T.Fog('#a9c59e', 15, 42);
  const camera = new T.PerspectiveCamera(42, 1, .1, 90);
  const renderer = new T.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'low-power' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = T.PCFSoftShadowMap;
  renderer.outputColorSpace = T.SRGBColorSpace;
  renderer.toneMapping = T.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.12;

  scene.add(new T.HemisphereLight('#e9ffd7', '#496448', 2.15));
  const sun = new T.DirectionalLight('#fff0c4', 3.2);
  sun.position.set(-7, 12, 8);
  sun.castShadow = true;
  sun.shadow.mapSize.set(1024, 1024);
  sun.shadow.camera.left = -16; sun.shadow.camera.right = 16;
  sun.shadow.camera.top = 16; sun.shadow.camera.bottom = -16;
  sun.shadow.bias = -.0004;
  scene.add(sun);

  const mat = (color, roughness = .88) => new T.MeshStandardMaterial({ color, roughness, flatShading: true });
  const groundMat = mat('#668b54');
  const ground = new T.Mesh(new T.PlaneGeometry(120, 120), groundMat);
  ground.rotation.x = -Math.PI / 2; ground.position.y = -.12; ground.receiveShadow = true; scene.add(ground);
  const pathMat = mat('#bca779');
  const pathShape = new T.Shape();
  pathShape.moveTo(-2.2, 9); pathShape.quadraticCurveTo(-3.1, 1, -.9, -5); pathShape.quadraticCurveTo(-.1, -12, -1.7, -24);
  pathShape.lineTo(1.9, -24); pathShape.quadraticCurveTo(.8, -11, 1.1, -5); pathShape.quadraticCurveTo(3.2, 2, 2.2, 9); pathShape.closePath();
  const trail = new T.Mesh(new T.ShapeGeometry(pathShape, 12), pathMat);
  trail.rotation.x = -Math.PI / 2; trail.position.y = -.095; trail.receiveShadow = true; scene.add(trail);
  // Little stones and fallen leaves give the trail a hand-built, tactile edge.
  const stoneMat = mat('#7a8060');
  for (let i = 0; i < 38; i++) {
    const z = 7 - Math.random() * 30;
    const side = Math.random() < .5 ? -1 : 1;
    const stone = new T.Mesh(new T.DodecahedronGeometry(.12 + Math.random() * .24, 0), stoneMat);
    stone.position.set(side * (2 + Math.random() * 1.1), .03, z);
    stone.scale.set(1.4, .55, .8); stone.rotation.y = Math.random() * 3; stone.castShadow = true; scene.add(stone);
  }
  const trunkMat = mat('#684b36'), leafMats = ['#31583d', '#3d6945', '#527b49', '#668950'].map(c => mat(c));
  function tree(x, z, scale, variant = 0) {
    const group = new T.Group(); group.position.set(x, 0, z); group.scale.setScalar(scale); scene.add(group);
    const trunk = new T.Mesh(new T.CylinderGeometry(.18, .3, 2.5, 6), trunkMat);
    trunk.position.y = 1.15; trunk.castShadow = true; group.add(trunk);
    if (variant % 2 === 0) {
      for (let n = 0; n < 3; n++) {
        const crown = new T.Mesh(new T.ConeGeometry(1.05 - n * .12, 1.7, 7), leafMats[(variant + n) % leafMats.length]);
        crown.position.y = 2.25 + n * .78; crown.castShadow = true; crown.receiveShadow = true; group.add(crown);
      }
    } else {
      const crown = new T.Mesh(new T.IcosahedronGeometry(1.3, 1), leafMats[variant % leafMats.length]);
      crown.position.y = 3.15; crown.scale.set(1, 1.12, .9); crown.castShadow = true; crown.receiveShadow = true; group.add(crown);
      const crown2 = new T.Mesh(new T.IcosahedronGeometry(.9, 1), leafMats[(variant + 1) % leafMats.length]);
      crown2.position.set(.56, 3.3, .22); crown2.castShadow = true; group.add(crown2);
    }
  }
  for (let i = 0; i < 34; i++) {
    const side = i % 2 ? 1 : -1;
    const z = 9 - Math.random() * 35;
    tree(side * (4.1 + Math.random() * 8), z, .75 + Math.random() * 1.15, i);
  }
  const shrubMats = ['#507944', '#6c9149', '#426b42'].map(c => mat(c));
  for (let i = 0; i < 32; i++) {
    const side = i % 2 ? 1 : -1;
    const bush = new T.Mesh(new T.IcosahedronGeometry(.45 + Math.random() * .48, 1), shrubMats[i % 3]);
    bush.position.set(side * (2.6 + Math.random() * 2.8), .3, 8 - Math.random() * 31);
    bush.scale.y = .65; bush.castShadow = true; bush.receiveShadow = true; scene.add(bush);
  }
  // Ferns and flowers in the foreground help sell the miniature diorama scale.
  for (let i = 0; i < 13; i++) {
    const x = (Math.random() < .5 ? -1 : 1) * (2.5 + Math.random() * 4);
    const z = 5 - Math.random() * 21;
    const fern = new T.Group(); fern.position.set(x, 0, z); scene.add(fern);
    for (let n = 0; n < 5; n++) {
      const leaf = new T.Mesh(new T.ConeGeometry(.12, .9 + Math.random() * .5, 5), leafMats[(i + n) % 4]);
      leaf.position.set((n - 2) * .14, .42, Math.abs(n - 2) * -.05);
      leaf.rotation.z = (n - 2) * .26; leaf.rotation.x = -.3; leaf.castShadow = true; fern.add(leaf);
    }
    if (i < 9) {
      const flower = new T.Mesh(new T.SphereGeometry(.12, 8, 6), mat(i % 2 ? '#f5d875' : '#f2e7cb'));
      flower.position.set(x * .12, .48, -.12); fern.add(flower);
    }
  }
  const fireflies = [];
  for (let i = 0; i < 12; i++) {
    const glow = new T.Mesh(new T.SphereGeometry(.045 + Math.random() * .035, 8, 6), new T.MeshBasicMaterial({ color: '#fff3a8' }));
    glow.position.set((Math.random() - .5) * 9, 1.2 + Math.random() * 3, -2 - Math.random() * 17);
    scene.add(glow); fireflies.push({ mesh: glow, phase: Math.random() * 6.28, base: glow.position.y });
  }
  // A soft sun disc sits in the sky; it is geometry, not a background image.
  const sunDisc = new T.Mesh(new T.SphereGeometry(1.1, 20, 12), new T.MeshBasicMaterial({ color: '#ffe6a1' }));
  sunDisc.position.set(-7, 9, -22); scene.add(sunDisc);

  const palette = {
    bulbasaur: { body: '#67aa82', head: '#72bd90', accent: '#438553', bulb: '#4c9864' },
    charmander: { body: '#ed8b48', head: '#f39b55', accent: '#d66c39', flame: '#ffb52e' },
    squirtle: { body: '#67b8d0', head: '#77c9df', accent: '#c88c58', shell: '#96694d' },
    pikachu: { body: '#f1cb4e', head: '#f5d65f', accent: '#bd5548' },
    eevee: { body: '#b77b4e', head: '#c68b59', accent: '#f1d5a5' },
    pidgey: { body: '#ad8157', head: '#c09465', accent: '#e8d0a1' },
    rattata: { body: '#9c6a9c', head: '#ae7dad', accent: '#e6b1a6' },
    oddish: { body: '#5276bd', head: '#688bd1', accent: '#60a858', bulb: '#66ad56' },
    bellsprout: { body: '#d2bd62', head: '#dfcf77', accent: '#57934c' },
    caterpie: { body: '#65ad67', head: '#78c979', accent: '#db5e56' },
    weedle: { body: '#bdac65', head: '#d3c47c', accent: '#df7657' }
  };
  const sphere = new T.SphereGeometry(1, 18, 12);
  let hero = null, heroKey = null, explorePulse = 0, targetYaw = 0, drag = null;
  function part(parent, geometry, material, pos, scale, rot) {
    const mesh = new T.Mesh(geometry, material); mesh.position.set(...pos); mesh.scale.set(...scale);
    if (rot) mesh.rotation.set(...rot); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
  }
  function makeHero(key = 'bulbasaur') {
    if (hero) { hero.traverse(o => { if (o.isMesh) { o.geometry.dispose(); if (Array.isArray(o.material)) o.material.forEach(m => m.dispose()); else o.material.dispose(); } }); scene.remove(hero); }
    heroKey = key;
    const colors = palette[key] || { body: '#d3a66d', head: '#e2bd82', accent: '#886447' };
    const bodyMat = mat(colors.body), headMat = mat(colors.head), detailMat = mat(colors.accent), white = mat('#fff8e8'), black = mat('#24352b'), belly = mat(key === 'squirtle' ? '#e5c7a2' : colors.accent);
    hero = new T.Group(); hero.position.set(-1.05, 0, 2.1); scene.add(hero);
    part(hero, sphere, bodyMat, [0, .66, 0], [.65, .56, .82]);
    part(hero, sphere, headMat, [0, 1.2, .34], [.61, .58, .54]);
    part(hero, sphere, belly, [0, .62, .68], [.39, .34, .17]);
    // Four short, rounded legs and tiny toes.
    for (const x of [-.4, .4]) for (const z of [-.42, .48]) {
      part(hero, sphere, bodyMat, [x, .25, z], [.22, .31, .23]);
      for (let t = -1; t <= 1; t++) part(hero, sphere, headMat, [x + t * .1, .08, z + .08], [.055, .05, .07]);
    }
    // Friendly face, facing toward the camera.
    for (const x of [-.23, .23]) {
      part(hero, sphere, white, [x, 1.29, .79], [.115, .145, .055]);
      part(hero, sphere, black, [x + .015, 1.28, .84], [.055, .085, .027]);
      part(hero, sphere, white, [x + .025, 1.32, .865], [.022, .028, .012]);
    }
    part(hero, new T.SphereGeometry(.045, 8, 6), detailMat, [0, 1.08, .85], [.8, .65, .5]);
    if (key === 'bulbasaur' || key === 'oddish') {
      part(hero, new T.IcosahedronGeometry(.53, 1), mat(colors.bulb || '#65a64f'), [0, 1.93, .12], [.8, .9, .8]);
      for (const [x, y, z] of [[-.31, 2.13, .52], [.3, 1.84, .51], [.05, 2.31, .41], [-.42, 1.79, .29]]) part(hero, sphere, mat('#a6c76a'), [x, y, z], [.09, .12, .045]);
      for (const x of [-.36, .36]) part(hero, new T.ConeGeometry(.16, .43, 5), detailMat, [x, 1.67, .1], [.8, 1, .8], [0, 0, x < 0 ? -.38 : .38]);
    } else if (key === 'charmander') {
      for (const x of [-.38, .38]) part(hero, new T.ConeGeometry(.13, .4, 5), headMat, [x, 1.72, .18], [.8, 1, .8], [0, 0, x < 0 ? -.35 : .35]);
      const tail = new T.Mesh(new T.CatmullRomCurve3([new T.Vector3(0, .55, -.65), new T.Vector3(.26, .36, -1.05), new T.Vector3(.55, .48, -1.3)]).getPoints(16).length > 1 ? new T.TubeGeometry(new T.CatmullRomCurve3([new T.Vector3(0, .55, -.65), new T.Vector3(.26, .36, -1.05), new T.Vector3(.55, .48, -1.3)]), 16, .09, 8, false) : sphere, detailMat);
      tail.castShadow = true; hero.add(tail);
      part(hero, new T.ConeGeometry(.17, .42, 7), mat(colors.flame), [.58, .74, -1.3], [1, 1.3, 1], [0, 0, -.2]);
      part(hero, new T.SphereGeometry(.1, 10, 8), mat('#fff0a0'), [.58, .67, -1.27], [1, 1.4, 1]);
    } else if (key === 'squirtle') {
      part(hero, new T.SphereGeometry(.62, 16, 10), mat(colors.shell), [0, .72, -.36], [1.05, 1, .46]);
      part(hero, new T.SphereGeometry(.49, 16, 10), mat('#e0b879'), [0, .75, .02], [1, .84, .15]);
      for (const x of [-.35, .35]) part(hero, new T.ConeGeometry(.14, .36, 5), headMat, [x, 1.68, .18], [.8, 1, .8], [0, 0, x < 0 ? -.3 : .3]);
    } else {
      for (const x of [-.4, .4]) part(hero, new T.ConeGeometry(.15, .38, 5), headMat, [x, 1.68, .2], [.8, 1, .8], [0, 0, x < 0 ? -.4 : .4]);
      if (key === 'pikachu') for (const x of [-.48, .48]) part(hero, sphere, mat('#e65f4f'), [x, 1.1, .65], [.13, .1, .05]);
      if (key === 'eevee') part(hero, new T.ConeGeometry(.24, .45, 6), mat('#e8d7b4'), [0, 1.61, .15], [.85, 1, .8]);
    }
    // Two subtle blush dots and a leaf tuft personalize the small forest friends.
    if (key !== 'bulbasaur' && key !== 'squirtle' && key !== 'charmander') {
      for (const x of [-.37, .37]) part(hero, sphere, detailMat, [x, 1.08, .73], [.09, .06, .035]);
    }
    hero.userData.baseY = 0;
  }

  let width = 1, height = 1, elapsed = 0;
  function resize() {
    const rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    width = rect.width; height = rect.height;
    renderer.setSize(width, height, false);
    camera.aspect = width / height; camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize, { passive: true });
  const observer = new ResizeObserver(resize); observer.observe(canvas);
  canvas.addEventListener('pointerdown', e => { drag = { x: e.clientX, yaw: targetYaw }; canvas.setPointerCapture(e.pointerId); });
  canvas.addEventListener('pointermove', e => { if (drag) targetYaw = Math.max(-.8, Math.min(.8, drag.yaw + (e.clientX - drag.x) * .007)); });
  canvas.addEventListener('pointerup', () => { drag = null; });
  canvas.addEventListener('pointercancel', () => { drag = null; });
  canvas.addEventListener('wheel', e => { e.preventDefault(); camera.position.z = Math.max(8, Math.min(14, camera.position.z + e.deltaY * .006)); }, { passive: false });

  function render(now) {
    requestAnimationFrame(render);
    elapsed = now * .001;
    if (hero) {
      const walking = explorePulse > 0 ? Math.sin(elapsed * 15) * .11 : 0;
      hero.position.y = Math.abs(walking) + Math.sin(elapsed * 2.2) * .045;
      hero.rotation.y += ((targetYaw * .18) - hero.rotation.y) * .035;
      if (explorePulse > 0) explorePulse = Math.max(0, explorePulse - .018);
    }
    fireflies.forEach(f => {
      f.mesh.position.y = f.base + Math.sin(elapsed * 1.8 + f.phase) * .18;
      f.mesh.material.opacity = .58 + Math.sin(elapsed * 2.4 + f.phase) * .35;
    });
    camera.position.x += ((Math.sin(targetYaw) * 1.5) - camera.position.x) * .025;
    camera.lookAt(0, 1.05, -2.4);
    renderer.render(scene, camera);
  }
  makeHero('bulbasaur'); resize(); requestAnimationFrame(render);
  window.forest3d = {
    setPokemon(key) { if (key && key !== heroKey) makeHero(key); },
    explore() { explorePulse = 1.4; targetYaw += (Math.random() - .5) * .26; },
    setZone(zone) { scene.fog.far = zone > 1 ? 34 : zone > 0 ? 39 : 44; }
  };
})();

