/* Real-time 3D scene canvas and gentle cinematic UI overlays. */
.scene-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:pan-y;cursor:grab;outline:0}
.scene-canvas:active{cursor:grabbing}
